    @Test
    public void testSanitize() {
        // Test case 1: Empty string
        Assert.assertEquals("", ArchiveUtils.sanitize(""));

        // Test case 2: String within the maximum length
        String original = "Hello, World!";
        String sanitized = ArchiveUtils.sanitize(original);
        Assert.assertNotEquals(original, sanitized);

        // Test case 3: String exceeding the maximum length
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < ArchiveUtils.MAX_SANITIZED_NAME_LENGTH + 10; i++) {
            sb.append("a");
        }
        String longString = sb.toString();
        String sanitizedLongString = ArchiveUtils.sanitize(longString);
        Assert.assertEquals(ArchiveUtils.MAX_SANITIZED_NAME_LENGTH, sanitizedLongString.length());
        for (int i = ArchiveUtils.MAX_SANITIZED_NAME_LENGTH - 3; i < ArchiveUtils.MAX_SANITIZED_NAME_LENGTH; i++) {
            Assert.assertEquals('.', sanitizedLongString.charAt(i));
        }

        // Test case 4: String containing special characters
        String specialChars = "\n\t\r";
        String sanitizedSpecialChars = ArchiveUtils.sanitize(specialChars);
        Assert.assertEquals("???", sanitizedSpecialChars);

        // Test case 5: String containing non-ISO control characters
        String nonISOCtrl = "\uD800\uDC00"; // surrogate pair
        String sanitizedNonISOCtrl = ArchiveUtils.sanitize(nonISOCtrl);
        Assert.assertEquals("??", sanitizedNonISOCtrl);

        // Test case 6: String containing ISO control characters
        String isoCtrl = "\u0000\u0001\u0002";
        String sanitizedISOCtrl = ArchiveUtils.sanitize(isoCtrl);
        Assert.assertEquals("???", sanitizedISOCtrl);

        // Test case 7: String containing SPECIALS Unicode block characters
        String specialBlock = "\uFFF0\uFFF1\uFFF2";
        String sanitizedSpecialBlock = ArchiveUtils.sanitize(specialBlock);
        Assert.assertEquals("???", sanitizedSpecialBlock);
    }
}
