public class BitInputStreamTest{
@Rule
    public final ExpectedException thrown = ExpectedException.none();

    private BitInputStream bitInputStream;

    @Before
    public void init() throws Exception {
        bitInputStream = new BitInputStream(new ByteArrayInputStream(new byte[]{}), ByteOrder.BIG_ENDIAN);
    }

    @Test
    public void testReadBits_NegativeCount_Throws() throws Exception {
        thrown.expect(IllegalArgumentException.class);
        bitInputStream.readBits(-1);
    }

    @Test
    public void testReadBits_TooLargeCount_Throws() throws Exception {
        thrown.expect(IllegalArgumentException.class);
        bitInputStream.readBits(64);
    }

    @Test
    public void testReadBits_ZeroCount_ReturnsZero() throws Exception {
        bitInputStream = new BitInputStream(new ByteArrayInputStream(new byte[]{}), ByteOrder.BIG_ENDIAN);
        assertEquals(0, bitInputStream.readBits(0));
    }

    @Test
    public void testReadBits_OneBit_ReturnsBit() throws Exception {
        bitInputStream = new BitInputStream(new ByteArrayInputStream(new byte[]{1}), ByteOrder.BIG_ENDIAN);
        assertEquals(1, bitInputStream.readBits(1));
    }

    @Test
    public void testReadBits_OneByte_ReturnsByte() throws Exception {
        bitInputStream = new BitInputStream(new ByteArrayInputStream(new byte[]{1}), ByteOrder.BIG_ENDIAN);
        assertEquals(1, bitInputStream.readBits(8));
    }

    @Test
    public void testReadBits_MultipleBytes_ReturnsBytes() throws Exception {
        bitInputStream = new BitInputStream(new ByteArrayInputStream(new byte[]{1,2,3}), ByteOrder.BIG_ENDIAN);
        assertEquals(0x010203L, bitInputStream.readBits(24));
    }

    @Test
    public void testReadBits_InsufficientData_ReturnsAvailableData() throws Exception {
        bitInputStream = new BitInputStream(new ByteArrayInputStream(new byte[]{1}), ByteOrder.BIG_ENDIAN);
        assertEquals(0x01L, bitInputStream.readBits(16));
    }

    @Test
    public void testReadBits_LittleEndian() throws Exception {
        bitInputStream = new BitInputStream(new ByteArrayInputStream(new byte[]{1,2,3}), ByteOrder.LITTLE_ENDIAN);
        assertEquals(0x030201L, bitInputStream.readBits(24));
    }

    @Test
    public void testReadBits_PartialByte() throws Exception {
        bitInputStream = new BitInputStream(new ByteArrayInputStream(new byte[]{1}), ByteOrder.BIG_ENDIAN);
        bitInputStream.readBits(4);
        assertEquals(1, bitInputStream.readBits(4));
    }

    @Test
    public void testClose() throws Exception {
        bitInputStream.close();
        // a bit tricky; check whether close is idempotent
        bitInputStream.close();
    }

    @Test
    public void testClearBitCache() throws Exception {
        bitInputStream.readBits(1);
        bitInputStream.clearBitCache();
        assertEquals(0, bitInputStream.readBits(1));
    }

}
