public class CpioArchiveOutputStreamTest{
private OutputStream out;
    private CpioArchiveOutputStream cpioArchiveOutputStream;

    @Before
    public void before(){
        try{
            out = new java.io.ByteArrayOutputStream();
            cpioArchiveOutputStream = new CpioArchiveOutputStream(out);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    @After
    public void after(){
        try{
            cpioArchiveOutputStream.close();
            out.close();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    @Test
    public void testClose() throws IOException {
        assertFalse(cpioArchiveOutputStream.closed);
        cpioArchiveOutputStream.close();
        assertTrue(cpioArchiveOutputStream.closed);
    }

    @Test
    public void testCloseTwice() throws IOException {
        cpioArchiveOutputStream.close();
        cpioArchiveOutputStream.close();
    }

    @Test
    public void testCloseThrowsIOException() throws IOException {
        OutputStream out = mock(OutputStream.class);
        doThrow(new IOException()).when(out).close();
        CpioArchiveOutputStream cpioArchiveOutputStream = new CpioArchiveOutputStream(out);
        try {
            cpioArchiveOutputStream.close();
            Assert.fail();
        } catch (IOException e) {
            // expected
        }
    }

    @Test
    public void testConstructors() throws Exception{
        CpioArchiveOutputStream cpioArchiveOutputStream = new CpioArchiveOutputStream(out);
        Assert.assertNotNull(cpioArchiveOutputStream.out);
        Assert.assertEquals(CpioArchiveOutputStream.FORMAT_NEW,cpioArchiveOutputStream.entryFormat);

        cpioArchiveOutputStream = new CpioArchiveOutputStream(out,CpioArchiveOutputStream.FORMAT_NEW);
        Assert.assertNotNull(cpioArchiveOutputStream.out);
        Assert.assertEquals(CpioArchiveOutputStream.FORMAT_NEW,cpioArchiveOutputStream.entryFormat);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testConstructorsWithUnknownFormat() throws Exception{
        CpioArchiveOutputStream cpioArchiveOutputStream = new CpioArchiveOutputStream(out,(short)100);
    }

    @Test
    public void testEnsureOpen() throws IOException {
        cpioArchiveOutputStream.ensureOpen();
        cpioArchiveOutputStream.close();
        try {
            cpioArchiveOutputStream.ensureOpen();
            Assert.fail();
        } catch (IOException e) {
            // expected
        }
    }
}
