public class TarArchiveOutputStreamTest{
private OutputStream os;
    private TarArchiveOutputStream tos;
    @Before
    public void setUp() throws Exception {
        os = new java.io.ByteArrayOutputStream();
        tos = new TarArchiveOutputStream(os);
    }

    @After
    public void tearDown() throws Exception {
        tos = null;
        os = null;
    }

    @Test
    public void testCloseNotClosed() throws IOException {
        Assert.assertFalse(tos.closed);
        tos.close();
        Assert.assertTrue(tos.closed);
    }

    @Test
    public void testCloseClosed() throws IOException {
        tos.close();
        tos.close();
        // No exception expected
    }

    @Test(expected = IOException.class)
    public void testCloseIOException() throws IOException {
        // mock buffer.close to throw IOException
        TarBuffer buffer = mock(TarBuffer.class);
        doThrow(IOException.class).when(buffer).close();
        tos.buffer = buffer;
        tos.close();
    }

    @Test
    public void testCloseDoesNotThrowIfBufferCloseDoesNotThrow() throws IOException {
        // mock buffer.close to do nothing
        TarBuffer buffer = mock(TarBuffer.class);
        tos.buffer = buffer;
        tos.out.close();
        tos.close();
        // No exception expected
    }

    @Test
    public void testCloseCallsBufferClose() throws IOException {
        // mock buffer.close
        TarBuffer buffer = mock(TarBuffer.class);
        tos.buffer = buffer;
        tos.close();
        // verify buffer.close was called
        verify(buffer).close();
    }

