    public void readWithStartIndex() throws Exception{
        ZipArchiveEntry entry = zipArchiveInputStream.getNextZipEntry();
        byte[] buffer = new byte[20];
        int read = zipArchiveInputStream.read(buffer, 5, 10);
        assertThat(read, not(equalTo(-1)));
    }

